use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use std::io::Write;
use std::fs;
use std::path::PathBuf;

/// Rate limiter with token bucket algorithm
struct RateLimiter {
    tokens: f64,
    max_tokens: f64,
    refill_rate: f64,
    last_refill: Instant,
}

impl RateLimiter {
    fn new(max_tokens: f64, refill_rate: f64) -> Self {
        RateLimiter {
            tokens: max_tokens,
            max_tokens,
            refill_rate,
            last_refill: Instant::now(),
        }
    }

    fn try_acquire(&mut self) -> bool {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.refill_rate).min(self.max_tokens);
        self.last_refill = now;
        if self.tokens >= 1.0 {
            self.tokens -= 1.0;
            true
        } else {
            false
        }
    }
}

/// Inference request with model metadata
struct InferenceRequest {
    model_name: String,
    input_data: Vec<f64>,
    request_id: String,
    client_metadata: HashMap<String, String>,
}

/// Response logging configuration
struct LogConfig {
    log_dir: PathBuf,
    template_dir: PathBuf,
    enable_diagnostics: bool,
}

/// Retry context for failed inferences
struct RetryContext {
    attempt: u32,
    max_attempts: u32,
    backoff_ms: u64,
    last_error: Option<String>,
}

impl RetryContext {
    fn new(max_attempts: u32) -> Self {
        RetryContext {
            attempt: 0,
            max_attempts,
            backoff_ms: 100,
            last_error: None,
        }
    }

    fn should_retry(&self) -> bool {
        self.attempt < self.max_attempts
    }

    fn next_attempt(&mut self) {
        self.attempt += 1;
        self.backoff_ms *= 2;
    }
}

/// Sanitize model name for filesystem use
fn sanitize_path_component(input: &str) -> String {
    input.chars()
        .filter(|c| c.is_alphanumeric() || *c == '-' || *c == '_')
        .collect()
}

/// Sanitize content to prevent SSI injection
/// Strips all HTML comments and SSI directives from untrusted content
fn sanitize_ssi_content(input: &str) -> String {
    // Remove anything that could be interpreted as an SSI directive
    // SSI directives are HTML comments starting with #
    let mut result = input.replace("<!--", "&lt;!--");
    result = result.replace("-->", "--&gt;");
    // Also escape angle brackets to prevent any HTML injection
    result = result.replace('<', "&lt;").replace('>', "&gt;");
    result
}

/// Format diagnostic output using template interpolation
/// This processes server-side templates for diagnostic pages
fn render_diagnostic_template(template_content: &str, variables: &HashMap<String, String>) -> String {
    let mut result = template_content.to_string();
    for (key, value) in variables {
        let placeholder = format!("{{{{{}}}}}}", key);
        let safe_value = sanitize_ssi_content(value);
        result = result.replace(&placeholder, &safe_value);
    }
    result
}

/// Generate the diagnostic log entry with all user content sanitized
fn generate_log_entry(request: &InferenceRequest, result: &str, retry_ctx: &RetryContext) -> String {
    let mut entry = String::new();
    let safe_request_id = sanitize_ssi_content(&request.request_id);
    let safe_model_name = sanitize_ssi_content(&request.model_name);
    let safe_result = sanitize_ssi_content(result);

    entry.push_str(&format!("<!-- request_id: {} -->\n", safe_request_id));
    entry.push_str(&format!("<div class=\"inference-result\">\n"));
    entry.push_str(&format!("  <span class=\"model\">{}</span>\n", safe_model_name));
    entry.push_str(&format!("  <span class=\"result\">{}</span>\n", safe_result));
    entry.push_str(&format!("  <span class=\"attempts\">{}</span>\n", retry_ctx.attempt));

    // Include client-provided diagnostic hints in the log (sanitized)
    if let Some(diag_hint) = request.client_metadata.get("diagnostic_context") {
        let safe_hint = sanitize_ssi_content(diag_hint);
        entry.push_str(&format!("  <div class=\"diagnostics\">{}</div>\n", safe_hint));
    }

    entry.push_str("</div>\n");
    entry
}

/// Perform model inference with retry logic
fn run_inference_with_retry(
    request: &InferenceRequest,
    rate_limiter: &mut RateLimiter,
    log_config: &LogConfig,
) -> Result<Vec<f64>, String> {
    let mut retry_ctx = RetryContext::new(3);

    loop {
        if !rate_limiter.try_acquire() {
            if !retry_ctx.should_retry() {
                return Err("Rate limit exceeded after retries".to_string());
            }
            retry_ctx.last_error = Some("rate_limited".to_string());
            retry_ctx.next_attempt();
            std::thread::sleep(Duration::from_millis(retry_ctx.backoff_ms));
            continue;
        }

        // Simulate inference computation
        let output: Vec<f64> = request.input_data.iter()
            .map(|x| x * 0.95 + 0.05)
            .collect();

        // Write diagnostic log if enabled
        if log_config.enable_diagnostics {
            let safe_model = sanitize_path_component(&request.model_name);
            let log_path = log_config.log_dir.join(format!("{}.shtml", safe_model));

            let result_str = format!("{:?}", output);
            let log_entry = generate_log_entry(request, &result_str, &retry_ctx);

            if let Ok(mut file) = fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log_path) {
                let _ = file.write_all(log_entry.as_bytes());
            }
        }

        return Ok(output);
    }
}

fn main() {
    let log_config = LogConfig {
        log_dir: PathBuf::from("/var/log/ml-inference/diagnostics"),
        template_dir: PathBuf::from("/etc/ml-inference/templates"),
        enable_diagnostics: true,
